import * as React from "react";
import { createPortal } from "react-dom";
import {
  autoUpdate,
  flip,
  limitShift,
  offset,
  shift,
  useFloating,
} from "@floating-ui/react-dom";
import type { Placement } from "@floating-ui/react-dom";
import { PanelRightIcon, X } from "lucide-react";

import { cn } from "@/lib/utils";
import { focusEventElement } from "@/hooks/use-event-keyboard";
import { usePopoverDismiss } from "@/hooks/use-popover-dismiss";
import { Button } from "@/components/ui/button";
import { EventDetailPanel } from "./event-detail-panel";
import {
  isInsideCalendarPopover,
  useCalendarPopoverBoundary,
} from "./calendar-popover-context";
import { useCalendarRenderSlots } from "./calendar-provider";
import { useEventTitleFocus } from "./event-title-focus-context";
import type { CalendarEvent, EventPopoverAnchor } from "./week-view-types";

/** Gap between the anchor and the popover, in px */
const POPOVER_SIDE_OFFSET = 8;

/** Collision padding on the bottom, left and right edges, in px */
const POPOVER_COLLISION_PADDING = { bottom: 8, left: 16, right: 16 };

/** Elements of the panel that Tab can reach, in order */
function getTabbables(container: HTMLElement): HTMLElement[] {
  return Array.from(container.querySelectorAll<HTMLElement>("*")).filter(
    (el) =>
      el.tabIndex >= 0 &&
      !el.hidden &&
      !(el as HTMLButtonElement).disabled &&
      !(el instanceof HTMLInputElement && el.type === "hidden") &&
      el.getClientRects().length > 0 &&
      getComputedStyle(el).visibility !== "hidden",
  );
}

/**
 * Tab and Shift+Tab cycle inside the details, as Radix's non-modal popover
 * content does with a looping (not trapping) focus scope: Tab on the last
 * control moves to the first, Shift+Tab on the first moves to the last. From
 * the panel itself (focused by a press on a blank part of it), Tab enters at
 * the first control and Shift+Tab at the last.
 */
function loopFocus(e: React.KeyboardEvent<HTMLElement>) {
  if (e.key !== "Tab" || e.altKey || e.ctrlKey || e.metaKey) return;
  if (e.defaultPrevented) return;
  const panel = e.currentTarget;
  const tabbables = getTabbables(panel);
  const first = tabbables[0];
  const last = tabbables[tabbables.length - 1];
  const active = document.activeElement;
  if (!first || !last) {
    if (active === panel) e.preventDefault();
    return;
  }
  const edge = e.shiftKey ? first : last;
  if (active !== edge && active !== panel) return;
  const next = e.shiftKey ? last : first;
  e.preventDefault();
  next.focus({ preventScroll: true });
  if (next instanceof HTMLInputElement) next.select();
}

/**
 * The transform origin for each placement: the panel grows out of the side
 * and corner that face its anchor.
 */
const TRANSFORM_ORIGIN_BY_PLACEMENT: Record<Placement, string> = {
  top: "center bottom",
  "top-start": "left bottom",
  "top-end": "right bottom",
  bottom: "center top",
  "bottom-start": "left top",
  "bottom-end": "right top",
  left: "right center",
  "left-start": "right top",
  "left-end": "right bottom",
  right: "left center",
  "right-start": "left top",
  "right-end": "left bottom",
};

interface EventDetailPopoverProps {
  event: CalendarEvent;
  /** The panel's id, for the trigger's `aria-controls` */
  id?: string;
  /** What the popover is placed beside */
  anchor: EventPopoverAnchor;
  /**
   * The element that toggles the popover (the event itself). Presses and
   * focus on it don't close the popover, since its own click does.
   */
  triggerRef?: React.RefObject<Element | null>;
  onEventChange?: (event: CalendarEvent) => void;
  onClose: () => void;
  /** Callback for the expand button (e.g. dock to a side panel). Hidden when absent. */
  onExpand?: () => void;
  onPrevWeek?: () => void;
  onNextWeek?: () => void;
  /** Which side to prefer for the popover. Defaults to "right". */
  side?: "right" | "bottom" | "left" | "top";
  /** Alignment along the side axis. Defaults to "center". */
  align?: "start" | "center" | "end";
  /**
   * Override the top collision padding. When omitted the header height is
   * used so the popover never overlaps the weekday header. All-day events
   * live *inside* the header, so they pass a small value to avoid being
   * pushed off-screen.
   */
  collisionPaddingTop?: number;
}

/**
 * The event details in a popover beside `anchor`. It renders its own
 * floating layer instead of the shadcn/ui Popover, so it works the same
 * with the Radix and the Base UI styles.
 */
export function EventDetailPopover({
  event,
  id,
  anchor,
  triggerRef,
  onEventChange,
  onClose,
  onExpand,
  onPrevWeek,
  onNextWeek,
  side = "right",
  align = "center",
  collisionPaddingTop,
}: EventDetailPopoverProps) {
  const { boundary, headerHeight, view } = useCalendarPopoverBoundary();
  const { pendingEventId, clearPending } = useEventTitleFocus();
  const { renderEventDetails } = useCalendarRenderSlots();
  const panelRef = React.useRef<HTMLDivElement>(null);
  /** Just created by click-to-create: its title should be focused */
  const isNew = pendingEventId === event.id;

  /**
   * In day view the event trigger spans the full grid width, leaving no room
   * for a 320px popover on either side within the calendar container.
   * Skip the collision boundary so the popover stays within the viewport.
   */
  const isDayView = view === "day";
  const collisionBoundary = !isDayView && boundary ? [boundary] : [];
  const detectOverflowOptions = {
    padding: {
      top: collisionPaddingTop ?? headerHeight,
      ...POPOVER_COLLISION_PADDING,
    },
    boundary: collisionBoundary,
    altBoundary: collisionBoundary.length > 0,
  };
  const placement: Placement = align === "center" ? side : `${side}-${align}`;

  const {
    refs,
    floatingStyles,
    placement: placedAt,
  } = useFloating({
    open: true,
    placement,
    strategy: "fixed",
    // left/top rather than a transform: the enter animation animates the
    // transform, and would slide the panel in from the viewport's corner
    transform: false,
    whileElementsMounted: autoUpdate,
    middleware: [
      offset(POPOVER_SIDE_OFFSET),
      shift({
        mainAxis: true,
        crossAxis: false,
        limiter: limitShift(),
        ...detectOverflowOptions,
      }),
      flip(detectOverflowOptions),
    ],
  });

  // After every render: a ref object keeps its identity when its element
  // changes, and floating-ui ignores a reference it already has
  React.useLayoutEffect(() => {
    refs.setReference("current" in anchor ? anchor.current : anchor);
  });

  const setPanel = React.useCallback(
    (node: HTMLDivElement | null) => {
      panelRef.current = node;
      refs.setFloating(node);
    },
    [refs],
  );

  /**
   * Escape closes the popover before the keydown reaches the event. If focus
   * was on the event or in the details (which unmount and drop it), put it
   * back on the event once that has happened.
   */
  const handleEscapeKeyDown = React.useCallback(() => {
    const active = document.activeElement;
    if (!(active instanceof HTMLElement)) return;
    const hadFocus =
      active.dataset.eventId === event.id || isInsideCalendarPopover(active);
    if (!hadFocus) return;
    requestAnimationFrame(() => {
      if (document.activeElement && document.activeElement !== document.body) {
        return;
      }
      focusEventElement(boundary, event.id);
    });
  }, [boundary, event.id]);

  const dismissHandlers = usePopoverDismiss({
    panelRef,
    triggerRef,
    onEscape: handleEscapeKeyDown,
    onDismiss: onClose,
  });

  // Custom details get `isNew` for one render; the default panel clears the
  // request itself once it has focused the title
  React.useEffect(() => {
    if (!renderEventDetails || !isNew) return;
    clearPending();
  }, [renderEventDetails, isNew, clearPending]);

  const popoverHeaderActions = (
    <>
      {onExpand && (
        <Button
          variant="ghost"
          size="icon"
          className="size-7 text-[#C7C5C1] dark:text-[#595959]"
          onClick={(e) => {
            e.stopPropagation();
            onExpand();
          }}
          title="Dock to sidebar"
        >
          <PanelRightIcon className="size-4" />
        </Button>
      )}
      <Button
        variant="ghost"
        size="icon"
        className="size-7 text-[#C7C5C1] dark:text-[#595959]"
        onClick={(e) => {
          e.stopPropagation();
          onClose();
        }}
        title="Close"
      >
        <X className="size-4" />
      </Button>
    </>
  );

  // The provider measures its boundary after it mounts. Until then there is
  // nothing to place the panel against, and no way to tell whether the
  // calendar sits in a dialog: rendering once that is known keeps the panel
  // in one container, rather than moving it (and remounting it) a render later
  if (!boundary) return null;

  /**
   * Inside a dialog (or a sheet or drawer), the panel goes into that dialog
   * rather than the body: a modal dialog keeps focus inside its own element
   * and turns off pointer events on the rest of the page.
   */
  const portalContainer =
    boundary.closest<HTMLElement>('[role="dialog"], [role="alertdialog"]') ??
    document.body;

  return createPortal(
    <div
      ref={setPanel}
      id={id}
      role="dialog"
      aria-label="Event details"
      data-calendar-popover=""
      data-side={placedAt.split("-")[0]}
      tabIndex={-1}
      // The views' own click handlers never see a press in the details, or in
      // anything the details render in a portal
      onClick={(e) => e.stopPropagation()}
      onKeyDown={loopFocus}
      {...dismissHandlers}
      style={{
        ...floatingStyles,
        transformOrigin: TRANSFORM_ORIGIN_BY_PLACEMENT[placedAt],
      }}
      className={cn(
        "z-50 w-[320px] max-h-[80vh] overflow-y-auto rounded-lg border bg-popover/60 text-popover-foreground shadow-lg outline-hidden backdrop-blur-xl",
        "animate-in fade-in-0 zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
      )}
    >
      {renderEventDetails ? (
        renderEventDetails({ event, close: onClose, isNew })
      ) : (
        <EventDetailPanel
          event={event}
          onEventChange={onEventChange}
          onPrevWeek={onPrevWeek}
          onNextWeek={onNextWeek}
          headerActions={popoverHeaderActions}
          autoFocusTitle={isNew}
          onTitleAutoFocused={clearPending}
        />
      )}
    </div>,
    portalContainer,
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import {
  Check,
  Copy,
  Monitor,
  SquareDashed,
  TabletSmartphone,
  Trash2,
} from "lucide-react";

import { cn } from "@/lib/utils";
import { EVENT_COLORS } from "@/lib/event-utils";
import { useCalendarConfig } from "./calendar-provider";
import type {
  CalendarInfo,
  DetailedCalendarEvent,
  EventColor,
} from "./week-view-types";

const colorSwatchClass: Record<EventColor, string> = {
  red: "bg-event-red-border",
  orange: "bg-event-orange-border",
  yellow: "bg-event-yellow-border",
  green: "bg-event-green-border",
  blue: "bg-event-blue-border",
  purple: "bg-event-purple-border",
  gray: "bg-event-gray-border",
};

/** Calendars that share an account, listed under its email */
interface CalendarGroup {
  /** Account email shown above the group; absent for calendars without one */
  email?: string;
  calendars: CalendarInfo[];
}

/** Groups calendars by account email, keeping the order they were given in */
function groupCalendarsByEmail(calendars: CalendarInfo[]): CalendarGroup[] {
  const groups: CalendarGroup[] = [];
  for (const calendar of calendars) {
    const group = groups.find((g) => g.email === calendar.email);
    if (group) {
      group.calendars.push(calendar);
      continue;
    }
    groups.push({ email: calendar.email, calendars: [calendar] });
  }
  return groups;
}

interface EventContextMenuProps {
  /** The right-clicked event; "Block on calendar" sets its `calendarId` */
  event: DetailedCalendarEvent;
  position: { x: number; y: number };
  onClose: () => void;
  onEventChange?: (event: DetailedCalendarEvent) => void;
}

function MenuItem({
  className,
  children,
  onSelect,
}: {
  className?: string;
  children: React.ReactNode;
  onSelect?: () => void;
}) {
  return (
    <button
      type="button"
      className={cn(
        "relative flex w-full cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-xs outline-none select-none",
        "text-white hover:bg-[#303030] focus:bg-[#303030]",
        className,
      )}
      onClick={onSelect}
    >
      {children}
    </button>
  );
}

function Shortcut({ children }: { children: React.ReactNode }) {
  return <span className="ml-auto text-xs text-white/40">{children}</span>;
}

function Separator() {
  return <div className="-mx-1 my-1 h-px bg-[#303030]" />;
}

function SubMenu({
  trigger,
  children,
}: {
  trigger: React.ReactNode;
  children: React.ReactNode;
}) {
  const [open, setOpen] = React.useState(false);
  const timeoutRef = React.useRef<ReturnType<typeof setTimeout>>(null);

  function handleMouseEnter() {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setOpen(true);
  }

  function handleMouseLeave() {
    timeoutRef.current = setTimeout(() => setOpen(false), 150);
  }

  return (
    <div
      className="relative"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <button
        type="button"
        className={cn(
          "relative flex w-full cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-xs outline-none select-none",
          "text-white hover:bg-[#303030] focus:bg-[#303030]",
          open && "bg-[#303030]",
        )}
      >
        {trigger}
        <svg
          className="ml-auto size-4 text-white/60"
          xmlns="http://www.w3.org/2000/svg"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="m9 18 6-6-6-6" />
        </svg>
      </button>
      {open && (
        <div className="absolute left-full top-0 ml-1 min-w-[180px] rounded-sm border border-[#303030] bg-[#252525] p-1 shadow-lg">
          {children}
        </div>
      )}
    </div>
  );
}

export function EventContextMenu({
  event,
  position,
  onClose,
  onEventChange,
}: EventContextMenuProps) {
  const menuRef = React.useRef<HTMLDivElement>(null);
  const [adjustedPos, setAdjustedPos] = React.useState(position);
  const [ready, setReady] = React.useState(false);
  const { calendars } = useCalendarConfig();
  const currentColor = event.color ?? "blue";
  const calendarGroups = React.useMemo(
    () => groupCalendarsByEmail(calendars),
    [calendars],
  );

  React.useLayoutEffect(() => {
    const menu = menuRef.current;
    if (!menu) return;

    const menuHeight = menu.offsetHeight;
    const menuWidth = menu.offsetWidth;
    let y = position.y;
    let x = position.x;

    if (position.y + menuHeight > window.innerHeight) {
      y = position.y - menuHeight;
    }
    if (position.x + menuWidth > window.innerWidth) {
      x = position.x - menuWidth;
    }

    setAdjustedPos({ x, y });
    setReady(true);
  }, [position]);

  React.useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (!menuRef.current) return;
      if (menuRef.current.contains(e.target as Node)) return;
      onClose();
    }

    function handleEscape(e: KeyboardEvent) {
      if (e.key !== "Escape") return;
      onClose();
    }

    // Use capture to close before other handlers fire
    document.addEventListener("mousedown", handleClickOutside, true);
    document.addEventListener("keydown", handleEscape);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside, true);
      document.removeEventListener("keydown", handleEscape);
    };
  }, [onClose]);

  function handleColorSelect(color: EventColor) {
    onEventChange?.({ ...event, color });
    onClose();
  }

  function handleCalendarSelect(calendarId: string) {
    onEventChange?.({ ...event, calendarId });
    onClose();
  }

  return createPortal(
    <div
      ref={menuRef}
      className="fixed z-50 min-w-[200px] rounded-sm border border-[#303030] bg-[#252525] p-1 shadow-md animate-in fade-in-0 zoom-in-95 motion-reduce:animate-none"
      style={{
        top: adjustedPos.y,
        left: adjustedPos.x,
        opacity: ready ? 1 : 0,
      }}
    >
      {/* Color selector row */}
      <div className="flex items-center gap-1.5 px-2 py-1.5">
        {EVENT_COLORS.map((color) => (
          <button
            key={color}
            type="button"
            className={cn(
              "relative flex size-3 items-center justify-center rounded-xs",
              colorSwatchClass[color],
            )}
            onClick={() => handleColorSelect(color)}
          >
            {color === currentColor && <Check className="size-2 text-white" />}
          </button>
        ))}
      </div>

      {/* Block on calendar (only when the provider lists calendars) */}
      {calendarGroups.length > 0 && (
        <>
          <Separator />
          <SubMenu
            trigger={
              <>
                <Monitor className="size-3.5" />
                Block on calendar
              </>
            }
          >
            {calendarGroups.map((group) => (
              <React.Fragment key={group.email ?? ""}>
                {group.email && (
                  <div className="px-2 py-1 text-[10px] text-white/40">
                    {group.email}
                  </div>
                )}
                {group.calendars.map((cal) => (
                  <MenuItem
                    key={cal.id}
                    onSelect={() => handleCalendarSelect(cal.id)}
                  >
                    <div
                      className={cn(
                        "size-3 rounded-xs shrink-0",
                        colorSwatchClass[cal.color],
                      )}
                    />
                    {cal.name}
                  </MenuItem>
                ))}
              </React.Fragment>
            ))}
          </SubMenu>
        </>
      )}

      <Separator />

      {/* Cut / Copy / Duplicate */}
      <MenuItem>
        <SquareDashed className="size-3.5" />
        Cut
        <Shortcut>⌘X</Shortcut>
      </MenuItem>
      <MenuItem>
        <TabletSmartphone className="size-3.5" />
        Copy
        <Shortcut>⌘C</Shortcut>
      </MenuItem>
      <MenuItem>
        <Copy className="size-3.5" />
        Duplicate
        <Shortcut>⌘D</Shortcut>
      </MenuItem>

      <Separator />

      {/* Delete */}
      <MenuItem className="text-[#E56458] hover:!bg-[#DE5551] hover:!text-white focus:!bg-[#DE5551] focus:!text-white [&:hover>svg]:!text-white [&:focus>svg]:!text-white [&:hover>.ml-auto]:!text-white [&:focus>.ml-auto]:!text-white">
        <Trash2 className="size-3.5 text-[#E56458]" />
        Delete
        <Shortcut>delete</Shortcut>
      </MenuItem>
    </div>,
    document.body,
  );
}

"use client";

import * as React from "react";

import { isEventInsideCalendarPopover } from "@/components/calendar-popover-context";

/**
 * A trigger in the details whose popup is open: a menu, a select or a popover
 * in custom details. Radix and Base UI both set `aria-expanded` on it as soon
 * as the popup opens, before focus moves in.
 */
const OPEN_POPUP_TRIGGER_SELECTOR =
  '[aria-expanded="true"][aria-haspopup]:not([aria-haspopup="false"]), [aria-expanded="true"][role="combobox"]';

interface PopoverDismissOptions {
  /** The popover's panel */
  panelRef: React.RefObject<HTMLElement | null>;
  /** The element that toggles the popover itself; presses on it aren't outside */
  triggerRef?: React.RefObject<Element | null>;
  /** Called on Escape, before `onDismiss` */
  onEscape: () => void;
  onDismiss: () => void;
}

/** Spread on the panel, so the hook sees events from its React tree */
export interface PopoverDismissHandlers {
  onPointerDownCapture: (e: React.PointerEvent) => void;
  onFocusCapture: (e: React.FocusEvent) => void;
}

/**
 * Closes a popover the way a non-modal shadcn/ui popover does: on Escape, on
 * a press outside it and when focus moves outside it. Not outside: the panel
 * and everything in its React tree, including what it renders in portals (its
 * menus, a select's list in custom details); the trigger; and a layer opened
 * from the panel, which takes the press or the Escape for itself.
 *
 * On touch, a press outside closes the popover on the click that ends it, so
 * a scroll that starts outside doesn't.
 */
export function usePopoverDismiss({
  panelRef,
  triggerRef,
  onEscape,
  onDismiss,
}: PopoverDismissOptions): PopoverDismissHandlers {
  const onEscapeRef = React.useRef(onEscape);
  const onDismissRef = React.useRef(onDismiss);
  /**
   * The native pointerdown and focusin events that went through the panel's
   * React tree. The document listeners look their own event up here, which
   * holds however React's root sits: React's capture handlers run before
   * them whether React listens on a container (Vite) or on the document
   * itself (Next.js App Router).
   */
  const [insideEvents] = React.useState(() => new WeakSet<Event>());
  /**
   * The element last focused through the panel's React tree while outside
   * its DOM: focus is in a popup the details opened in a portal (a menu, a
   * select's list, or a popover opened from inside one of those).
   */
  const portalFocusRef = React.useRef<Element | null>(null);

  React.useEffect(() => {
    onEscapeRef.current = onEscape;
    onDismissRef.current = onDismiss;
  }, [onEscape, onDismiss]);

  React.useEffect(() => {
    /**
     * Whether a layer opened from the details is open: a trigger in the panel
     * says so, or focus sits in a popup the panel rendered in a portal. It
     * owns Escape and outside presses until it closes, the way stacked layers
     * behave in shadcn/ui. Layers opened anywhere else on the page don't
     * count.
     */
    function hasOpenLayer(): boolean {
      if (panelRef.current?.querySelector(OPEN_POPUP_TRIGGER_SELECTOR)) {
        return true;
      }
      const focused = portalFocusRef.current;
      return focused !== null && focused === document.activeElement;
    }

    function isOutside(e: Event): boolean {
      const target = e.target;
      if (!(target instanceof Node)) return false;
      if (insideEvents.has(e)) return false;
      if (triggerRef?.current?.contains(target)) return false;
      return !isEventInsideCalendarPopover(e);
    }

    function handleKeyDown(e: KeyboardEvent) {
      if (e.key !== "Escape" || hasOpenLayer()) return;
      // Marks the Escape as taken, as Radix layers do: a Radix dialog the
      // calendar sits in then leaves it to the details and stays open
      e.preventDefault();
      onEscapeRef.current();
      onDismissRef.current();
    }

    /** On touch, the click that ends the press; a scroll never fires one */
    let pendingClick: (() => void) | null = null;
    function clearPendingClick() {
      if (!pendingClick) return;
      document.removeEventListener("click", pendingClick);
      pendingClick = null;
    }
    function dismissOnClick() {
      pendingClick = null;
      onDismissRef.current();
    }

    /**
     * Whether a layer opened from the panel was open when the press began.
     * Read before the layer's own listeners can close it: a Base UI menu
     * closes on a capture listener added after this one.
     */
    let layerOpenOnPress = false;
    function notePointerDown() {
      layerOpenOnPress = hasOpenLayer();
    }

    function handlePointerDown(e: PointerEvent) {
      if (layerOpenOnPress || !isOutside(e)) {
        // A press inside cancels a touch outside still waiting for its click
        clearPendingClick();
        return;
      }
      if (e.pointerType !== "touch") {
        onDismissRef.current();
        return;
      }
      clearPendingClick();
      pendingClick = dismissOnClick;
      document.addEventListener("click", dismissOnClick, { once: true });
    }

    function handleFocusIn(e: FocusEvent) {
      if (hasOpenLayer() || !isOutside(e)) return;
      // Focus on an element the panel sits in (the dialog it's portaled into,
      // after a press on a blank part of it) hasn't left the panel
      const panel = panelRef.current;
      if (panel && e.target instanceof Node && e.target.contains(panel)) return;
      onDismissRef.current();
    }

    // Escape is handled first, on the window's capture phase: before the
    // calendar's own key handlers, and before a dialog's on the document
    window.addEventListener("keydown", handleKeyDown, true);
    document.addEventListener("pointerdown", notePointerDown, true);
    document.addEventListener("focusin", handleFocusIn);
    // Start listening for presses a tick later, so the press that opened the
    // popover doesn't close it
    const timer = window.setTimeout(() => {
      document.addEventListener("pointerdown", handlePointerDown);
    }, 0);

    return () => {
      window.clearTimeout(timer);
      window.removeEventListener("keydown", handleKeyDown, true);
      document.removeEventListener("pointerdown", notePointerDown, true);
      document.removeEventListener("focusin", handleFocusIn);
      document.removeEventListener("pointerdown", handlePointerDown);
      clearPendingClick();
    };
  }, [panelRef, triggerRef, insideEvents]);

  return React.useMemo(
    () => ({
      onPointerDownCapture: (e: React.PointerEvent) => {
        insideEvents.add(e.nativeEvent);
      },
      onFocusCapture: (e: React.FocusEvent) => {
        insideEvents.add(e.nativeEvent);
        const panel = panelRef.current;
        const target = e.target;
        const inPortal =
          target instanceof Element &&
          panel !== null &&
          !panel.contains(target);
        portalFocusRef.current = inPortal ? target : null;
      },
    }),
    [insideEvents, panelRef],
  );
}

import * as React from "react";

/**
 * Options for `useInlineEdit`
 */
export interface UseInlineEditOptions {
  /** The input's ref, used to blur it on Enter and Escape */
  inputRef: React.RefObject<HTMLInputElement | null>;
  /** Text the field shows while it isn't being edited, derived from the event */
  value: string;
  /**
   * Commits the typed text on blur or Enter. Returns the text to show
   * afterwards, or `null` to reject it and restore the text from focus.
   */
  onCommit: (text: string) => string | null;
  /** Called on every keystroke, e.g. to preview a title on the calendar */
  onInput?: (text: string) => void;
  /**
   * Called with the text from focus after Escape or a rejected commit, e.g.
   * to undo a preview
   */
  onRestore?: (text: string) => void;
}

/**
 * Props to spread on the `<input>` an inline edit drives (pass its ref
 * separately)
 */
export interface InlineEditInputProps {
  value: string;
  onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onFocus: () => void;
  onBlur: () => void;
  onKeyDown: (e: React.KeyboardEvent<HTMLInputElement>) => void;
}

/**
 * Value `useInlineEdit` returns
 */
export interface UseInlineEditResult {
  /** Text in the field right now, typed or derived */
  text: string;
  /** Spread on the `<input>` */
  inputProps: InlineEditInputProps;
}

/**
 * The details panel's inline edit pattern for one text field: local text
 * while typing, Enter commits by blurring, Escape restores the text from
 * focus without committing (and stops the key from reaching the calendar's
 * global Escape, which would deselect the event).
 */
export function useInlineEdit({
  inputRef,
  value,
  onCommit,
  onInput,
  onRestore,
}: UseInlineEditOptions): UseInlineEditResult {
  const [text, setText] = React.useState(value);
  /** Set by Escape so the blur that follows doesn't commit */
  const escapePressedRef = React.useRef(false);
  /** Text when the field gained focus, restored on Escape or a rejected commit */
  const valueOnFocusRef = React.useRef(value);

  // Follow the event while the field isn't being typed into
  React.useEffect(() => {
    setText(value);
  }, [value]);

  const handleChange = React.useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      setText(e.target.value);
      onInput?.(e.target.value);
    },
    [onInput],
  );

  const handleFocus = React.useCallback(() => {
    valueOnFocusRef.current = value;
  }, [value]);

  const handleBlur = React.useCallback(() => {
    if (escapePressedRef.current) {
      escapePressedRef.current = false;
      return;
    }
    const committed = onCommit(text);
    if (committed !== null) {
      setText(committed);
      return;
    }
    setText(valueOnFocusRef.current);
    onRestore?.(valueOnFocusRef.current);
  }, [onCommit, onRestore, text]);

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === "Enter") {
        e.preventDefault();
        inputRef.current?.blur();
        return;
      }
      if (e.key !== "Escape") return;
      e.preventDefault();
      e.stopPropagation();
      escapePressedRef.current = true;
      setText(valueOnFocusRef.current);
      onRestore?.(valueOnFocusRef.current);
      inputRef.current?.blur();
    },
    [inputRef, onRestore],
  );

  return {
    text,
    inputProps: {
      value: text,
      onChange: handleChange,
      onFocus: handleFocus,
      onBlur: handleBlur,
      onKeyDown: handleKeyDown,
    },
  };
}

import * as React from "react";

/**
 * Value `useHoverTooltip` returns
 */
export interface UseHoverTooltipResult {
  /** Whether the tooltip shows */
  isOpen: boolean;
  /** The pointer entered the trigger: opens after `TOOLTIP_OPEN_DELAY` */
  scheduleOpen: () => void;
  /** The pointer left the trigger or the tooltip: closes after `TOOLTIP_CLOSE_DELAY` */
  scheduleClose: () => void;
  /** The pointer reached the tooltip before it closed: keeps it open */
  keepOpen: () => void;
}

/** How long the pointer rests on a trigger before its tooltip shows, in ms */
const TOOLTIP_OPEN_DELAY = 500;

/** Time to move the pointer from a trigger onto its tooltip, in ms */
const TOOLTIP_CLOSE_DELAY = 120;

/**
 * Open state of a tooltip that shows after the pointer rests on its
 * trigger, and stays while the pointer moves onto it
 */
export function useHoverTooltip(): UseHoverTooltipResult {
  const [isOpen, setIsOpen] = React.useState(false);
  const timerRef = React.useRef<number | null>(null);

  const clearTimer = React.useCallback(() => {
    if (timerRef.current === null) return;
    window.clearTimeout(timerRef.current);
    timerRef.current = null;
  }, []);

  React.useEffect(() => clearTimer, [clearTimer]);

  const scheduleOpen = React.useCallback(() => {
    clearTimer();
    timerRef.current = window.setTimeout(
      () => setIsOpen(true),
      TOOLTIP_OPEN_DELAY,
    );
  }, [clearTimer]);

  const scheduleClose = React.useCallback(() => {
    clearTimer();
    timerRef.current = window.setTimeout(
      () => setIsOpen(false),
      TOOLTIP_CLOSE_DELAY,
    );
  }, [clearTimer]);

  return { isOpen, scheduleOpen, scheduleClose, keepOpen: clearTimer };
}

import * as React from "react";

/** Attribute marking a field's popover: focus moving into it comes straight back */
export const FIELD_POPOVER_ATTRIBUTE = "data-event-detail-field-popover";

/**
 * Options for `useFieldPopover`
 */
export interface UseFieldPopoverOptions {
  /** The field's input */
  inputRef: React.RefObject<HTMLInputElement | null>;
  /** Whether the field's popover is open */
  open: boolean;
  /** Focus came into the field: opens the popover */
  onEnter: () => void;
  /** Focus left the field, not by Escape or a pick: sets what was typed or chosen */
  onCommit: () => void;
  /** Escape: puts back the value from before the popover opened */
  onRestore: () => void;
  /** Closes the popover */
  onClose: () => void;
}

/**
 * Value `useFieldPopover` returns
 */
export interface UseFieldPopoverResult {
  /** Spread on the `<input>` */
  inputProps: {
    onFocus: (e: React.FocusEvent<HTMLInputElement>) => void;
    onBlur: (e: React.FocusEvent<HTMLInputElement>) => void;
  };
  /** Called as a press on the field's box starts */
  notePress: () => void;
  /** Called before the popover hands focus back to the input */
  noteReturnFocus: () => void;
  /** Escape: restores the value, closes the popover and leaves the field */
  escape: () => void;
  /** Closes the popover and leaves the field after a pick that set the value */
  leave: () => void;
}

/** Selects an input's text once React has put its new value in it */
export function selectInputSoon(
  inputRef: React.RefObject<HTMLInputElement | null>,
) {
  requestAnimationFrame(() => {
    const input = inputRef.current;
    if (input && document.activeElement === input) input.select();
  });
}

/** Whether focus is moving into a field popover (it comes straight back) */
function isFieldPopover(target: EventTarget | null): boolean {
  return (
    target instanceof Element &&
    target.closest(`[${FIELD_POPOVER_ATTRIBUTE}]`) !== null
  );
}

/**
 * Focus, blur and Escape for a details field with a popover (the time menu,
 * the date picker), following the panel's inline edit pattern: focus opens
 * the popover, blur commits and closes it, Escape restores the value and
 * leaves the field without committing.
 *
 * The popover libraries move focus as they open and close, and the hook
 * keeps it in the field:
 * - Opening, the popover takes focus and hands it back to the input; that
 *   focus isn't entering the field again.
 * - Escape reaches Radix and Base UI on the document, where Base UI stops
 *   it, so the hook takes it first on the window while the popover is open,
 *   and keeps it from the details' and the calendar's own Escape (which
 *   would deselect the event).
 * - Closing, Base UI hands focus back to the input it came from. After the
 *   field is left, a focus with no source is that hand-back until the field
 *   is pressed again, and it's turned away.
 */
export function useFieldPopover({
  inputRef,
  open,
  onEnter,
  onCommit,
  onRestore,
  onClose,
}: UseFieldPopoverOptions): UseFieldPopoverResult {
  const optionsRef = React.useRef({
    open,
    onEnter,
    onCommit,
    onRestore,
    onClose,
  });
  /** Set while the popover hands focus back to the input */
  const returningFocusRef = React.useRef(false);
  /** Set when the field is left with its popover open, until it's pressed again */
  const leftOpenRef = React.useRef(false);
  /** Set by Escape and a pick, whose blur must not commit again */
  const skipBlurCommitRef = React.useRef(false);

  React.useEffect(() => {
    optionsRef.current = { open, onEnter, onCommit, onRestore, onClose };
  }, [open, onEnter, onCommit, onRestore, onClose]);

  const leave = React.useCallback(() => {
    const wasOpen = optionsRef.current.open;
    optionsRef.current.onClose();
    const input = inputRef.current;
    if (!input || document.activeElement !== input) return;
    leftOpenRef.current = wasOpen;
    skipBlurCommitRef.current = true;
    input.blur();
  }, [inputRef]);

  const escape = React.useCallback(() => {
    optionsRef.current.onRestore();
    leave();
  }, [leave]);

  React.useEffect(() => {
    if (!open) return;
    function handleKeyDown(e: KeyboardEvent) {
      if (e.key !== "Escape" || document.activeElement !== inputRef.current) {
        return;
      }
      e.preventDefault();
      e.stopPropagation();
      escape();
    }
    window.addEventListener("keydown", handleKeyDown, true);
    return () => window.removeEventListener("keydown", handleKeyDown, true);
  }, [open, inputRef, escape]);

  const handleFocus = React.useCallback(
    (e: React.FocusEvent<HTMLInputElement>) => {
      if (returningFocusRef.current) {
        returningFocusRef.current = false;
        return;
      }
      if (leftOpenRef.current && e.relatedTarget === null) {
        leftOpenRef.current = false;
        skipBlurCommitRef.current = true;
        e.currentTarget.blur();
        return;
      }
      leftOpenRef.current = false;
      optionsRef.current.onEnter();
    },
    [],
  );

  const handleBlur = React.useCallback(
    (e: React.FocusEvent<HTMLInputElement>) => {
      if (isFieldPopover(e.relatedTarget)) return;
      if (skipBlurCommitRef.current) {
        skipBlurCommitRef.current = false;
        optionsRef.current.onClose();
        return;
      }
      optionsRef.current.onCommit();
      optionsRef.current.onClose();
    },
    [],
  );

  const notePress = React.useCallback(() => {
    leftOpenRef.current = false;
  }, []);

  const noteReturnFocus = React.useCallback(() => {
    returningFocusRef.current = true;
  }, []);

  return {
    inputProps: { onFocus: handleFocus, onBlur: handleBlur },
    notePress,
    noteReturnFocus,
    escape,
    leave,
  };
}

import {
  addDays,
  addMinutes,
  differenceInMinutes,
  format,
  parse,
  startOfDay,
} from "date-fns";
import type { Locale } from "date-fns";

import type {
  DetailedCalendarEvent,
  HourCycle,
  TimeOption,
} from "@/components/week-view-types";

/** Minutes between two options of the time menu, as in Notion Calendar */
const TIME_STEP_MINUTES = 15;

/** Minutes in a day on the wall clock */
const MINUTES_PER_DAY = 24 * 60;

/** Options in a day of the time menu: every TIME_STEP_MINUTES from midnight */
const TIME_OPTIONS_PER_DAY = MINUTES_PER_DAY / TIME_STEP_MINUTES;

/** A bare hour like "7" prefers the reading between 8 AM and 8 PM: 7 PM */
const DAYTIME_START_MINUTES = 8 * 60;

/** End of the daytime a bare hour prefers (8 PM) */
const DAYTIME_END_MINUTES = 20 * 60;

/**
 * A number typed as a duration below this reads as hours first ("2" → 2h,
 * then 2min), from it as minutes first ("45" → 45min, then 45h)
 */
const DURATION_HOURS_FIRST_BELOW = 15;

/** Longest duration a typed number may stand for: a week */
const MAX_TYPED_DURATION_MINUTES = 7 * 24 * 60;

/** Formats a time for the time menu: "4:15 PM", or "16:15" on a 24-hour clock */
type FormatTime = (date: Date) => string;

/** "45min", "2h" or "1h 30min" */
export function formatDuration(start: Date, end: Date): string {
  const totalMinutes = differenceInMinutes(end, start);

  if (totalMinutes < 60) {
    return `${totalMinutes}min`;
  }

  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;

  if (minutes === 0) {
    return `${hours}h`;
  }

  return `${hours}h ${minutes}min`;
}

/**
 * Returns a new Date with the same year/month/day as `base`
 * but with hours and minutes replaced.
 */
export function applyTimeToDate(
  base: Date,
  hours: number,
  minutes: number,
): Date {
  const result = new Date(base);
  result.setHours(hours, minutes, 0, 0);
  return result;
}

/**
 * The time `minutes` after midnight on `day`'s wall clock, or null when the
 * clock skips it (2:30 AM on the day daylight saving time starts). Counting
 * elapsed minutes from midnight instead would land an hour off on that day
 * and on the day it ends.
 */
function clockTime(day: Date, minutes: number): Date | null {
  const date = applyTimeToDate(day, Math.floor(minutes / 60), minutes % 60);
  if (date.getHours() * 60 + date.getMinutes() !== minutes) return null;
  return date;
}

/** Minutes typed after an hour: "3" means 30 ("7:3" → 7:30), "7" means 07 ("3:7" → 3:07) */
function readTypedMinutes(digits: string): number {
  if (digits.length === 0) return 0;
  if (digits.length > 1) return Number(digits);
  const digit = Number(digits);
  return digit < 6 ? digit * 10 : digit;
}

/** Text typed in a time field, lowercased, without spaces or dots */
function normalizeTyped(text: string): string {
  return text.toLowerCase().replace(/[\s.]/g, "");
}

/**
 * Times of day (minutes from midnight) typed text can mean, best first, as
 * Notion Calendar reads them: "7" → 7 PM, 7 AM; "9" → 9 AM, 9 PM (a bare
 * hour prefers 8 AM–8 PM); "12" → 12 PM, 12 AM, 1:20 PM, 1:20 AM (the first
 * digit as the hour too); "930" → 9:30 AM, 9:30 PM; "7:3p" → 7:30 PM. On a
 * 24-hour clock a bare hour reads as written first: "7" → 07:00, 19:00.
 */
function readTypedTimes(text: string, hourCycle: HourCycle): number[] {
  const match = /^(\d{1,4})(?::(\d{0,2}))?(a|am|p|pm)?$/.exec(
    normalizeTyped(text),
  );
  if (!match) return [];
  const [, digits, colonMinutes, period] = match;

  const readings: Array<{ hour: number; minute: number }> = [];
  if (colonMinutes !== undefined) {
    if (digits.length <= 2) {
      readings.push({
        hour: Number(digits),
        minute: readTypedMinutes(colonMinutes),
      });
    }
  } else {
    if (digits.length <= 2) {
      readings.push({ hour: Number(digits), minute: 0 });
    }
    if (digits.length >= 2 && digits.length <= 3) {
      readings.push({
        hour: Number(digits[0]),
        minute: readTypedMinutes(digits.slice(1)),
      });
    }
    if (digits.length >= 3) {
      readings.push({
        hour: Number(digits.slice(0, 2)),
        minute: readTypedMinutes(digits.slice(2)),
      });
    }
  }

  const times: number[] = [];
  for (const { hour, minute } of readings) {
    if (minute > 59) continue;
    for (const minutes of readHour(hour, period, hourCycle)) {
      const time = minutes + minute;
      if (!times.includes(time)) times.push(time);
    }
  }
  return times;
}

/**
 * Minutes from midnight an hour can mean, best first: one with "am"/"pm" or
 * outside 1–12, the daytime one first otherwise
 */
function readHour(
  hour: number,
  period: string | undefined,
  hourCycle: HourCycle,
): number[] {
  if (period) {
    if (hour < 1 || hour > 12) return [];
    const isPm = period.startsWith("p");
    return [((hour % 12) + (isPm ? 12 : 0)) * 60];
  }
  if (hour > 23) return [];
  if (hour === 0 || hour > 12) return [hour * 60];

  const morning = (hour % 12) * 60;
  const evening = morning + 12 * 60;
  if (hourCycle === 24) return [hour * 60, hour === 12 ? 0 : evening];
  const isDaytime = (minutes: number) =>
    minutes >= DAYTIME_START_MINUTES && minutes < DAYTIME_END_MINUTES;
  if (isDaytime(evening) && !isDaytime(morning)) return [evening, morning];
  return [morning, evening];
}

/**
 * Durations (minutes) typed text can mean in the end field, best first:
 * "2" → 2h, 2min; "45" → 45min, 45h; "8:30" → 8h 30min; "1h30" → 1h 30min.
 * Text with "am" or "pm" is a time, never a duration.
 */
function readTypedDurations(text: string): number[] {
  const typed = normalizeTyped(text);
  const durations: number[] = [];

  const units = /^(?:(\d{1,3})h)?(?:(\d{1,4})(?:m|min|mins)?)?$/.exec(typed);
  const clock = /^(\d{1,3})(?::(\d{0,2}))?$/.exec(typed);
  if (clock) {
    const [, digits, colonMinutes] = clock;
    const number = Number(digits);
    if (colonMinutes !== undefined) {
      const minutes = readTypedMinutes(colonMinutes);
      if (minutes < 60) durations.push(number * 60 + minutes);
    } else if (number < DURATION_HOURS_FIRST_BELOW) {
      durations.push(number * 60, number);
    } else {
      durations.push(number, number * 60);
    }
  } else if (units && (units[1] || units[2])) {
    durations.push(Number(units[1] ?? 0) * 60 + Number(units[2] ?? 0));
  }

  return durations.filter(
    (minutes, index) =>
      minutes > 0 &&
      minutes <= MAX_TYPED_DURATION_MINUTES &&
      durations.indexOf(minutes) === index,
  );
}

/** The dates in order, each time once */
function uniqueDates(dates: Date[]): Date[] {
  return dates.filter(
    (date, index) =>
      dates.findIndex((other) => other.getTime() === date.getTime()) === index,
  );
}

/** The options' list with `value` in its place, when it's between two steps */
function withValue(options: TimeOption[], value: TimeOption): TimeOption[] {
  const time = value.date.getTime();
  if (options.some((option) => option.date.getTime() === time)) {
    return options;
  }
  const index = options.findIndex((option) => option.date.getTime() > time);
  if (index === -1) return [...options, value];
  return [...options.slice(0, index), value, ...options.slice(index)];
}

/**
 * Every 15 minutes of `day` on its wall clock: 96 times, 92 on the day
 * daylight saving time starts (the skipped hour), and each 1 AM–1:45 AM
 * once on the day it ends
 */
function getDayTimes(day: Date): Date[] {
  const midnight = startOfDay(day);
  const times: Date[] = [];
  for (let i = 0; i < TIME_OPTIONS_PER_DAY; i++) {
    const date = clockTime(midnight, i * TIME_STEP_MINUTES);
    if (date) times.push(date);
  }
  return times;
}

/** Every 15 minutes after `start` on the wall clock, up to the same time a day later */
function getTimesAfter(start: Date): Date[] {
  const midnight = startOfDay(start);
  const startMinutes = start.getHours() * 60 + start.getMinutes();
  const times: Date[] = [];
  for (let i = 1; i <= TIME_OPTIONS_PER_DAY; i++) {
    const minutes = startMinutes + i * TIME_STEP_MINUTES;
    const day = addDays(midnight, Math.floor(minutes / MINUTES_PER_DAY));
    const date = clockTime(day, minutes % MINUTES_PER_DAY);
    if (date && date > start) times.push(date);
  }
  return times;
}

/**
 * Whether an event ends after the midnight that closes its first day, so
 * its end time needs a date (an end at that midnight doesn't)
 */
export function endsOnLaterDay(start: Date, end: Date): boolean {
  return end > addDays(startOfDay(start), 1);
}

/** The start time menu: every 15 minutes of the start's day, with the start in its place */
export function getStartTimeOptions(
  start: Date,
  formatTime: FormatTime,
): TimeOption[] {
  const options = getDayTimes(start).map((date) => ({
    date,
    label: formatTime(date),
  }));
  return withValue(options, { date: start, label: formatTime(start) });
}

/**
 * The end time menu, each option with how long the event lasts: every 15
 * minutes after the start for a day, or every 15 minutes of the end's day
 * for an event that ends on a later day; the end in its place
 */
export function getEndTimeOptions(
  start: Date,
  end: Date,
  formatTime: FormatTime,
): TimeOption[] {
  const toOption = (date: Date): TimeOption => ({
    date,
    label: formatTime(date),
    hint: formatDuration(start, date),
  });
  const dates = endsOnLaterDay(start, end)
    ? getDayTimes(end).filter((date) => date > start)
    : getTimesAfter(start);
  const options = dates.map(toOption);
  return end > start ? withValue(options, toOption(end)) : options;
}

/** Start times typed text can mean on the start's day, best first */
export function matchStartTimes(
  text: string,
  start: Date,
  hourCycle: HourCycle,
  formatTime: FormatTime,
): TimeOption[] {
  const midnight = startOfDay(start);
  return readTypedTimes(text, hourCycle).flatMap((minutes) => {
    const date = clockTime(midnight, minutes);
    return date ? [{ date, label: formatTime(date) }] : [];
  });
}

/**
 * End times typed text can mean, best first, with how long the event lasts:
 * times of the end's day after the start (the next day's when they aren't),
 * then durations from the start
 */
export function matchEndTimes(
  text: string,
  start: Date,
  end: Date,
  hourCycle: HourCycle,
  formatTime: FormatTime,
): TimeOption[] {
  const midnight = startOfDay(endsOnLaterDay(start, end) ? end : start);
  const dates: Date[] = [];
  for (const minutes of readTypedTimes(text, hourCycle)) {
    const sameDay = clockTime(midnight, minutes);
    const date =
      sameDay && sameDay > start
        ? sameDay
        : clockTime(addDays(midnight, 1), minutes);
    if (date) dates.push(date);
  }
  for (const minutes of readTypedDurations(text)) {
    dates.push(addMinutes(start, minutes));
  }
  return uniqueDates(dates).map((date) => ({
    date,
    label: formatTime(date),
    hint: formatDuration(start, date),
  }));
}

/** "Sat Jun 6", in the calendar's locale */
export function formatDateDisplay(date: Date, locale: Locale): string {
  return format(date, "EEE MMM d", { locale });
}

/**
 * Parses a user-typed date string into a Date.
 * Strips any leading weekday name and parses "MMM d" (e.g., "Mar 11") in
 * the calendar's locale. Uses the reference date's year. Returns null if
 * unparseable.
 */
export function parseDateInput(
  input: string,
  referenceDate: Date,
  locale: Locale,
): Date | null {
  const trimmed = input.trim();
  if (trimmed.length === 0) {
    return null;
  }

  // Strip an optional leading weekday ("Tue ", "sáb ") when a month name follows
  const withoutWeekday = trimmed.replace(/^[^\s\d]+\s+(?=[^\s\d])/, "");

  const parsed = parse(withoutWeekday, "MMM d", referenceDate, { locale });
  if (Number.isNaN(parsed.getTime())) {
    return null;
  }

  return parsed;
}

/** Whether the event has a time of day (an all-day event's are all midnight) */
export function hasTimeOfDay(event: DetailedCalendarEvent): boolean {
  return (
    event.start.getHours() !== 0 ||
    event.start.getMinutes() !== 0 ||
    event.end.getHours() !== 0 ||
    event.end.getMinutes() !== 0
  );
}
